e_count'));?>"></div><div class="col-md-4 mb-3"><label class="form-label">Ukuran</label><input class="form-control" name="dimensions" value="<?=html_escape($f('dimensions'));?>" placeholder="21 × 16 cm"></div><div class="col-md-4 mb-3"><label class="form-label">Kondisi</label><input class="form-control" name="condition_state" value="<?=html_escape($f('condition_state'));?>" placeholder="Baik / rapuh / perlu konservasi"></div></div><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Asal</label><input class="form-control" name="origin" value="<?=html_escape($f('origin'));?>" placeholder="Kabupaten Rembang"></div><div class="col-md-6 mb-3"><label class="form-label">Periode / Tahun Perkiraan</label><input class="form-control" name="estimated_period" value="<?=html_escape($f('estimated_period'));?>" placeholder="Akhir abad XIX"></div></div><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Penulis / Penyalin</label><input class="form-control" name="author_scribe" value="<?=html_escape($f('author_scribe'));?>"></div><div class="col-md-6 mb-3"><label class="form-label">Lokasi Simpan Fisik</label><input class="form-control" name="current_location" value="<?=html_escape($f('current_location'));?>" placeholder="Ruang Koleksi Khusus"></div></div><div class="mb-3"><label class="form-label">Deskripsi Isi</label><textarea class="form-control" rows="5" name="description" placeholder="Naskah memuat ..."><?=html_escape($f('description'));?></textarea></div><div class="mb-3"><label class="form-label">Riwayat Koleksi / Provenans</label><textarea class="form-control" rows="4" name="collection_history" placeholder="Koleksi diperoleh dari ..."><?=html_escape($f('collection_history'));?></textarea></div><div class="mb-0"><label class="form-label">Catatan Konservasi</label><textarea class="form-control" rows="3" name="conservation_notes" placeholder="Kondisi jilidan, tinta, kerusakan, atau tindakan konservasi."><?=html_escape($f('conservation_notes'));?></textarea></div></div></div></div><div class="col-lg-4"><div class="card admin-card mb-3"><div class="card-header"><h2 class="card-title">Digitalisasi dan Akses</h2></div><div class="card-body"><div class="mb-3"><label class="form-label">Tanggal Digitalisasi</label><input type="date" class="form-control" name="digitized_at" value="<?=html_escape($f('digitized_at'));?>"></div><div class="mb-3"><label class="form-label">Petugas / Mitra Digitalisasi</label><input class="form-control" name="digitized_by" value="<?=html_escape($f('digitized_by'));?>"></div><div class="mb-3"><label class="form-label">Catatan Digitalisasi</label><textarea class="form-control" rows="3" name="digitization_notes" placeholder="Resolusi scan, perangkat, jumlah citra, dan pengolahan."><?=html_escape($f('digitization_notes'));?></textarea></div><div class="mb-3"><label class="form-label">Hak / Catatan Pemanfaatan</label><textarea class="form-control" rows="3" name="rights_note" placeholder="Contoh: untuk riset dan pendidikan, wajib menyebut sumber."><?=html_escape($f('rights_note'));?></textarea></div><div class="mb-3"><label class="form-label">Cover Naskah</label><input class="form-control" type="file" name="cover" accept="image/jpeg,image/png,image/webp"><div class="form-hint">JPG, PNG, atau WEBP; maksimal 200 MB.</div></div><div class="mb-3"><label class="form-label">Preview Digital Tunggal</label><input class="form-control" type="file" name="preview_file" accept="application/pdf,image/jpeg,image/png,image/webp"><div class="form-hint">Opsional: PDF atau satu citra scan, maksimal 200 MB.</div><?php if($f('preview_file_path')):?><a target="_blank" class="small d-inline-block mt-2" href="<?=base_url('naskah-kuno/preview/'.(int)$f('id'));?>"><i class="ti ti-eye me-1"></i>Lihat preview saat ini</a><?php endif;?></div><div class="mb-3"><label class="form-label">Halaman Digital</label><input class="form-control" type="file" name="page_images[]" multiple accept="image/jpeg,image/png,image/webp"><div class="form-hint">Unggah beberapa citra halaman sekaligus (JPG, PNG, WEBP; total maksimal 200 MB per simpan). Unggah bertahap bila scan lebih besar. Urutan file menjadi urutan halaman dan disimpan aman di storage.</div><?php if(!empty($pages)):?><div class="mt-2 small text-secondary"><i class="ti ti-files me-1"></i><?=count($pages);?> halaman sudah tersedia di viewer.</div><?php endif;?></div><div class="mb-3"><label class="form-label">Akses Digital</label><select class="form-select" name="access_level"><option value="public" <?=$f('access_level','public')==='public'?'selected':'';?>>Publik</option><option value="member" <?=$f('access_level')==='member'?'selected':'';?>>Member login</option><option value="internal" <?=$f('access_level')==='internal'?'selected':'';?>>Internal petugas</option></select></div><div class="mb-3"><label class="form-label">Status Publikasi</label><select class="form-select" name="status"><option value="draft" <?=$f('status','draft')==='draft'?'selected':'';?>>Draft</option><option value="published" <?=$f('status')==='published'?'selected':'';?>>Tayang</option><option value="archived" <?=$f('status')==='archived'?'selected':'';?>>Arsip</option></select></div><label class="form-check mb-3"><input class="form-check-input" type="checkbox" name="is_featured" value="1" <?=!empty($f('is_featured'))?'checked':'';?>><span class="form-check-label">Tampilkan sebagai koleksi unggulan</span></label><button class="btn btn-primary w-100"><i class="ti ti-device-floppy me-1"></i>Simpan Naskah</button></div></div><div class="alert alert-info"><i class="ti ti-shield-lock me-1"></i>Citra halaman dan preview tidak diberi URL file langsung. Sistem memeriksa level akses sebelum mengirimkan berkas.</div><?php if($edit&&!empty($pages)):?><div class="card admin-card"><div class="card-header"><h2 class="card-title">Halaman yang Tersedia</h2></div><div class="list-group list-group-flush"><?php foreach($pages as $page):?><div class="list-group-item d-flex align-items-center gap-2"><span class="badge bg-azure-lt text-azure">Hal. <?= (int)$page['page_number'];?></span><span class="small text-secondary text-truncate flex-fill"><?=html_escape($page['original_name']?:'Citra halaman');?></span><?=form_open('manuscripts/page/'.(int)$f('id').'/delete/'.(int)$page['id'],['class'=>'d-inline']);?><button class="btn btn-sm btn-outline-danger" data-confirm="Hapus halaman ini dari viewer? Berkas sumber tetap disimpan pada arsip aman." data-confirm-title="Hapus Halaman"><i class="ti ti-trash"></i></button><?=form_close();?></div><?php endforeach;?></div></div><?php endif;?></div></div><?=form_close();?></div></div>
