<div class="manuscript-save-modal" id="manuscript-save-modal" aria-live="assertive" aria-hidden="true"><div class="manuscript-save-dialog"><div class="manuscript-save-spinner"></div><h2>Menyimpan rekam naskah</h2><p>Metadata dan berkas digital sedang diproses. Jangan menutup halaman ini.</p></div></div>
<script>
(function(){var form=document.getElementById('manuscript-form'),modal=document.getElementById('manuscript-save-modal');if(!form||!modal)return;form.addEventListener('submit',function(event){if(!form.checkValidity())return;var limit=200*1024*1024,total=0,inputs=[form.querySelector('[name="cover"]'),form.querySelector('[name="preview_file"]'),form.querySelector('[name="page_images[]"]')];for(var i=0;i<inputs.length;i++){var input=inputs[i];if(!input)continue;for(var j=0;j<input.files.length;j++){total+=input.files[j].size;if(input.files[j].size>limit||total>limit){event.preventDefault();input.setCustomValidity('Total unggahan dalam satu kali simpan maksimal 200 MB. Unggah halaman secara bertahap.');input.reportValidity();input.setCustomValidity('');return;}}}modal.classList.add('is-open');modal.setAttribute('aria-hidden','false');var button=form.querySelector('button[type="submit"]');if(button){button.disabled=true;button.innerHTML='<span class="spinner-border spinner-border-sm me-1"></span>Menyimpan...';}});})();
</script>
